const throughput = [
  { hour: "08", orders: 44 }, { hour: "09", orders: 58 }, { hour: "10", orders: 39 }, { hour: "11", orders: 63 }, { hour: "12", orders: 68 }, { hour: "13", orders: 55 }, { hour: "14", orders: 61 },
];

