function formatViewTitle(view: View) {
  return { command: "Command desk", orders: "Order queue", inventory: "Inventory radar", pick: "Pick & pack", dispatch: "Dispatch board", analytics: "Flow analysis" }[view];
}

function ShiftMenu({ shift, onChange, className }: { shift: Shift; onChange: (shift: Shift) => void; className?: string }) {
  const [open, setOpen] = useState(false);
  return <div className={cn("relative", className)}>
    <button type="button" className="flex items-center gap-2 rounded-full border border-ink/10 px-3 py-1.5 text-[10px] font-semibold" onClick={() => setOpen(current => !current)} aria-haspopup="menu" aria-expanded={open}>
      <span className="h-1.5 w-1.5 rounded-full bg-sage" /> Shift {shift} <span className="font-mono text-ink/45">{shiftDetails[shift].time.split("–")[0]}</span><ChevronRight className={cn("h-3 w-3 text-ink/35 transition", open ? "rotate-90" : "rotate-0")} />
    </button>
    {open ? <div role="menu" className="absolute right-0 top-[calc(100%+8px)] z-50 w-64 rounded-2xl border border-ink/10 bg-paper p-2 text-ink shadow-[0_18px_50px_rgba(15,40,55,0.18)]">
      <div className="px-3 pb-2 pt-2 font-mono text-[8px] uppercase tracking-[0.18em] text-ink/40">Change operating shift</div>
      {(["A", "B", "C"] as Shift[]).map(option => <button type="button" role="menuitem" key={option} onClick={() => { onChange(option); setOpen(false); toast.success(`Shift ${option} selected`, { description: `${shiftDetails[option].label} shift · ${shiftDetails[option].status}` }); }} className={cn("flex w-full items-start gap-3 rounded-xl px-3 py-2.5 text-left transition hover:bg-[#f7f1e6]", shift === option && "bg-[#f7f1e6]")}><span className={cn("mt-0.5 flex h-6 w-6 items-center justify-center rounded-full font-mono text-[9px] font-bold", shift === option ? "bg-signal text-ink" : "bg-ink/7 text-ink/55")}>{option}</span><span className="min-w-0 flex-1"><span className="block text-[11px] font-semibold">Shift {option} · {shiftDetails[option].label}</span><span className="mt-0.5 block font-mono text-[8px] uppercase tracking-[0.12em] text-ink/40">{shiftDetails[option].time}</span><span className="mt-1 block text-[10px] text-ink/45">{shiftDetails[option].status}</span></span>{shift === option ? <Check className="mt-1 h-3.5 w-3.5 text-sage-dark" /> : null}</button>)}
    </div> : null}
  </div>;
}

function AppShell({ view, setView, children, onSearch, shift, onShiftChange }: { view: View; setView: (view: View) => void; children: React.ReactNode; onSearch: () => void; shift: Shift; onShiftChange: (shift: Shift) => void }) {
  const [mobileNavOpen, setMobileNavOpen] = useState(false);
  const handleNavigation = (nextView: View) => { setView(nextView); setMobileNavOpen(false); };
  return (
    <div className="min-h-screen bg-paper text-ink lg:flex">
      <aside className="sticky top-0 z-30 hidden h-screen w-[250px] shrink-0 flex-col overflow-y-auto bg-ink px-5 py-4 text-white lg:flex">
        <button className="flex items-center gap-3 text-left" onClick={() => setView("command")} aria-label="Go to Command desk">
          <span className="flex h-10 w-10 items-center justify-center rounded-[12px] bg-signal p-2 shadow-[0_8px_24px_rgba(231,168,59,0.2)]">
            <img src="/manus-storage/warehouseiq-route-mark_89e4c0e0.png" alt="WarehouseIQ route mark" className="h-full w-full object-contain" />
          </span>
          <span>
            <span className="block font-display text-[22px] italic leading-none tracking-[-0.04em]">Warehouse<span className="text-signal">IQ</span></span>
            <span className="mt-1 block font-mono text-[9px] uppercase tracking-[0.2em] text-white/45">Flow command</span>
          </span>
        </button>

        <button className="mt-6 flex items-center justify-between rounded-xl border border-white/10 bg-white/[0.06] px-3 py-3 text-left transition hover:bg-white/[0.1]" onClick={() => toast("Facility selector is set to Northline FC-01") }>
          <span className="flex items-center gap-2.5"><Warehouse className="h-4 w-4 text-signal" /><span><span className="block text-[12px] font-semibold">Northline Fulfillment</span><span className="font-mono text-[9px] uppercase tracking-[0.16em] text-white/40">FC-01 · Manchester</span></span></span>
          <ChevronRight className="h-4 w-4 rotate-90 text-white/35" />
        </button>

        <div className="mt-6">
          <div className="mb-3 px-3 font-mono text-[9px] uppercase tracking-[0.24em] text-white/35">Operations</div>
          <nav className="space-y-1.5">
            {navItems.map((item) => {
              const Icon = item.icon;
              const active = view === item.id;
              return <button key={item.id} onClick={() => handleNavigation(item.id)} className={cn("group flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-[12px] transition", active ? "bg-[#fbf5e9] font-semibold text-ink shadow-[0_8px_20px_rgba(0,0,0,0.12)]" : "text-white/63 hover:bg-white/[0.08] hover:text-white")}><Icon className={cn("h-4 w-4", active ? "text-signal" : "text-white/45 group-hover:text-signal")} /><span className="flex-1">{item.label}</span>{item.count ? <span className={cn("rounded-full px-1.5 py-0.5 font-mono text-[9px]", active ? "bg-ink/10 text-ink/65" : "bg-white/10 text-white/50")}>{item.count}</span> : null}</button>;
            })}
          </nav>
        </div>

        <div className="mt-auto rounded-2xl border border-white/10 bg-white/[0.05] p-3.5">
          <div className="flex items-center gap-2 font-mono text-[9px] uppercase tracking-[0.2em] text-white/40"><span className="h-1.5 w-1.5 animate-pulse rounded-full bg-sage" /> Live shift status</div>
          <div className="mt-3 font-display text-[21px] leading-[1.04]">Steady, with one call.</div>
          <div className="mt-3 text-[11px] leading-relaxed text-white/48">48 orders active · 76% floor capacity · 1 exception needs a lead decision.</div>
        </div>
        <button className="mt-4 flex items-center gap-3 border-t border-white/10 pt-4 text-left" onClick={() => toast("Profile settings are available from the shift menu") }><span className="flex h-8 w-8 items-center justify-center rounded-full bg-signal text-[11px] font-bold text-ink">NT</span><span className="flex-1"><span className="block text-[11px] font-semibold">Nina Torres</span><span className="font-mono text-[8px] uppercase tracking-[0.16em] text-white/38">Fulfillment lead</span></span><Settings2 className="h-4 w-4 text-white/35" /></button>
      </aside>

      <div className="min-w-0 flex-1">
        <div className="flex items-center justify-between border-b border-ink/10 bg-paper px-5 py-3 lg:hidden">
          <button onClick={() => setView("command")} className="flex items-center gap-2"><span className="flex h-8 w-8 items-center justify-center rounded-lg bg-signal p-1.5"><img src="/manus-storage/warehouseiq-route-mark_89e4c0e0.png" alt="" /></span><span className="font-display text-lg italic">Warehouse<span className="text-signal-dark">IQ</span></span></button>
          <button type="button" className="rounded-lg border border-ink/10 p-2" onClick={() => setMobileNavOpen(current => !current)} aria-label="Open operations menu" aria-expanded={mobileNavOpen}><Menu className="h-4 w-4" /></button>
        </div>
        <header className="flex h-[76px] items-center justify-between border-b border-ink/10 px-5 sm:px-8">
          <div className="flex items-center gap-3 text-[11px] text-ink/48"><span className="font-mono uppercase tracking-[0.18em]">Northline FC-01</span><span className="h-1 w-1 rounded-full bg-signal" /><span>Tuesday, 14 October</span><span className="hidden text-ink/30 sm:inline">·</span><span className="hidden font-mono uppercase tracking-[0.16em] text-ink/42 sm:inline">Shift {shift} · {shiftDetails[shift].time}</span></div>
          <div className="flex items-center gap-2"><button className="hidden rounded-lg p-2 text-ink/45 transition hover:bg-ink/5 hover:text-ink sm:inline-flex" onClick={onSearch} aria-label="Open search"><Search className="h-4 w-4" /></button><button className="rounded-lg p-2 text-ink/45 transition hover:bg-ink/5 hover:text-ink" onClick={() => toast("No new notifications") } aria-label="Notifications"><Bell className="h-4 w-4" /></button><ShiftMenu shift={shift} onChange={onShiftChange} className="hidden sm:block" /></div>
        </header>
        {mobileNavOpen ? <div className="fixed inset-0 z-40 bg-ink/25 lg:hidden" onClick={() => setMobileNavOpen(false)}><aside className="h-full w-[290px] bg-ink p-5 text-white shadow-[18px_0_60px_rgba(15,40,55,0.2)]" onClick={event => event.stopPropagation()}><div className="flex items-center justify-between"><div className="font-mono text-[9px] uppercase tracking-[0.2em] text-white/45">Operations menu</div><button type="button" onClick={() => setMobileNavOpen(false)} className="rounded-lg p-2 text-white/55 hover:bg-white/10 hover:text-white" aria-label="Close operations menu"><X className="h-4 w-4" /></button></div><div className="mt-5"><ShiftMenu shift={shift} onChange={onShiftChange} className="block" /></div><nav className="mt-6 space-y-1.5">{navItems.map(item => { const Icon = item.icon; const active = view === item.id; return <button type="button" key={item.id} onClick={() => handleNavigation(item.id)} className={cn("flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-[12px] transition", active ? "bg-[#fbf5e9] font-semibold text-ink" : "text-white/65 hover:bg-white/[0.08] hover:text-white")}><Icon className={cn("h-4 w-4", active ? "text-signal" : "text-white/45")} /><span className="flex-1">{item.label}</span>{item.count ? <span className={cn("rounded-full px-1.5 py-0.5 font-mono text-[9px]", active ? "bg-ink/10 text-ink/65" : "bg-white/10 text-white/50")}>{item.count}</span> : null}</button>; })}</nav><div className="mt-8 border-t border-white/10 pt-5 text-[11px] leading-relaxed text-white/45">Tap any workspace to switch views. Shift changes apply to the active control-room context.</div></aside></div> : null}
        <main className="px-5 pb-14 pt-8 sm:px-8 lg:px-10">{children}</main>
      </div>
    </div>
  );
}

function Eyebrow({ children, className }: { children: React.ReactNode; className?: string }) { return <div className={cn("mb-3 flex items-center gap-2 font-mono text-[9px] uppercase tracking-[0.24em] text-ink/45", className)}><span className="h-1.5 w-1.5 rounded-full bg-signal" />{children}</div>; }
function PageIntro({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) { return <div className="mb-8 flex flex-col justify-between gap-5 border-b border-ink/10 pb-7 sm:flex-row sm:items-end"><div><Eyebrow>{eyebrow}</Eyebrow><h1 className="max-w-3xl font-display text-[42px] leading-[0.95] tracking-[-0.045em] text-ink sm:text-[52px]">{title}</h1><p className="mt-4 max-w-xl text-[13px] leading-relaxed text-ink/55">{description}</p></div>{action}</div>; }
function Metric({ label, value, change, accent = "ink" }: { label: string; value: string; change?: string; accent?: "ink" | "signal" | "sage" }) { return <div className="min-w-0"><div className="font-mono text-[9px] uppercase tracking-[0.2em] text-ink/40">{label}</div><div className={cn("mt-2 font-display text-[30px] leading-none tracking-[-0.04em]", accent === "signal" ? "text-signal-dark" : accent === "sage" ? "text-sage-dark" : "text-ink")}>{value}</div>{change ? <div className="mt-1 text-[10px] text-ink/45">{change}</div> : null}</div>; }
function Pill({ children, active, onClick }: { children: React.ReactNode; active?: boolean; onClick?: () => void }) { return <button onClick={onClick} className={cn("rounded-full border px-3 py-1.5 text-[10px] transition", active ? "border-ink bg-ink text-paper" : "border-ink/15 bg-transparent text-ink/55 hover:border-ink/35 hover:text-ink")}>{children}</button>; }
function Panel({ children, className }: { children: React.ReactNode; className?: string }) { return <section className={cn("rounded-2xl border border-ink/10 bg-card shadow-[0_12px_40px_rgba(15,40,55,0.04)]", className)}>{children}</section>; }

function FlowTrack({ active = 4 }: { active?: number }) {
  const steps = ["Order created", "Prioritised", "Allocated", "Picking", "Packing", "Quality check", "Dispatch"];
  return <div className="overflow-x-auto rounded-2xl border border-ink/10 bg-[#f7f1e6] px-5 py-4"><div className="mb-3 flex items-center justify-between font-mono text-[9px] uppercase tracking-[0.2em] text-ink/42"><span>Today's fulfillment flow</span><span>{active}/7 active</span></div><div className="flex min-w-[670px] items-center">{steps.map((step, index) => { const completed = index + 1 < active; const current = index + 1 === active; return <div key={step} className="flex flex-1 items-center"><div className="flex items-center gap-2"><span className={cn("flex h-6 w-6 items-center justify-center rounded-full border text-[10px] font-bold", completed ? "border-sage bg-sage text-white" : current ? "border-signal bg-signal text-ink" : "border-ink/15 bg-paper text-ink/35")}>{completed ? <Check className="h-3.5 w-3.5" /> : index + 1}</span><span className={cn("whitespace-nowrap text-[10px]", current ? "font-semibold text-ink" : "text-ink/43")}>{step}</span></div>{index < steps.length - 1 ? <div className={cn("mx-3 h-px flex-1", completed ? "bg-sage/60" : "bg-ink/12")} /> : null}</div>; })}</div></div>;
}

function DecisionCard({ resolved, onResolve, onReview }: { resolved: boolean; onResolve: () => void; onReview: () => void }) {
  return <Panel className={cn("overflow-hidden border-l-[3px]", resolved ? "border-l-sage" : "border-l-signal")}><div className="p-5 sm:p-6"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><div><div className="flex items-center gap-2 font-mono text-[9px] uppercase tracking-[0.22em] text-signal-dark"><span className={cn("flex h-5 w-5 items-center justify-center rounded-full", resolved ? "bg-sage text-white" : "bg-signal/20")}>{resolved ? <Check className="h-3 w-3" /> : <AlertTriangle className="h-3 w-3" />}</span>{resolved ? "Decision resolved · audit logged" : "Decision required · SLA risk"}</div><h2 className="mt-3 font-display text-[29px] leading-none tracking-[-0.035em]">{resolved ? "SO-48219 is protected." : "Protect SO-48219 before 16:00."}</h2><p className="mt-3 max-w-2xl text-[12px] leading-relaxed text-ink/55">{resolved ? "Seven units moved to the urgent wave. Three inbound units remain linked to the split shipment, and Marlowe Market's reservation was moved to tomorrow." : "Nova Retail needs 10 LUMA-200 units but only 7 are available. Release the lower-priority reservation, allocate the available units now, and split-ship the inbound balance."}</p></div><div className="flex shrink-0 gap-2"><Button variant="outline" size="sm" onClick={onReview} className="h-9 border-ink/15 bg-transparent text-[11px]">Review impact</Button><Button size="sm" onClick={onResolve} disabled={resolved} className="h-9 bg-signal text-ink hover:bg-signal-dark disabled:bg-sage disabled:text-white">{resolved ? <><Check className="mr-1.5 h-3.5 w-3.5" /> Approved</> : <>Approve allocation <ChevronRight className="ml-1.5 h-3.5 w-3.5" /></>}</Button></div></div><div className="mt-5 grid grid-cols-2 gap-3 border-t border-ink/10 pt-4 sm:grid-cols-4"><div><div className="font-display text-[22px]">10</div><div className="font-mono text-[8px] uppercase tracking-[0.18em] text-ink/42">urgent demand</div></div><div><div className="font-display text-[22px]">7</div><div className="font-mono text-[8px] uppercase tracking-[0.18em] text-ink/42">available now</div></div><div><div className="font-display text-[22px] text-sage-dark">+3</div><div className="font-mono text-[8px] uppercase tracking-[0.18em] text-ink/42">inbound @ 14:20</div></div><div><div className="font-display text-[22px] text-signal-dark">1</div><div className="font-mono text-[8px] uppercase tracking-[0.18em] text-ink/42">SLA at risk</div></div></div><div className="mt-4 flex flex-wrap items-center gap-2 font-mono text-[8px] uppercase tracking-[0.18em] text-ink/38"><span>01 allocate</span><span className="text-ink/18">→</span><span>02 pick zone A</span><span className="text-ink/18">→</span><span>03 pack-02</span><span className="text-ink/18">→</span><span>04 dock-01</span></div></div></Panel>;
}

function OrderRow({ order, onOpen }: { order: Order; onOpen: (order: Order) => void }) {
  return <button onClick={() => onOpen(order)} className="group grid w-full grid-cols-[1.4fr_1.1fr_0.5fr_0.8fr_0.55fr] items-center gap-3 border-t border-ink/8 px-5 py-4 text-left transition hover:bg-[#fbf6ec] sm:px-6"><div className="min-w-0"><div className="flex items-center gap-2"><span className={cn("rounded px-1.5 py-0.5 font-mono text-[8px] font-bold", order.priority === "URG" ? "bg-signal/20 text-signal-dark" : order.priority === "HIGH" ? "bg-[#f1e5bd] text-[#81661c]" : "bg-ink/7 text-ink/45")}>{order.priority}</span><span className="truncate text-[12px] font-semibold">{order.customer}</span></div><div className="mt-1 font-mono text-[9px] text-ink/40">{order.id} · {order.sku}</div></div><div className="min-w-0"><div className="truncate text-[11px] text-ink/65">{order.status}</div><div className="mt-1 font-mono text-[9px] text-ink/35">{order.zone}</div></div><div className="font-mono text-[11px] text-ink/65">{order.allocated} / {order.units}</div><div><span className={cn("rounded-full border px-2 py-1 text-[9px]", statusTone[order.risk])}>{order.risk}</span><div className="mt-1 font-mono text-[8px] text-ink/38">{order.promise}</div></div><ChevronRight className="h-4 w-4 justify-self-end text-ink/22 transition group-hover:translate-x-0.5 group-hover:text-signal-dark" /></button>;
}

function CommandDesk({ setView, decisionResolved, onResolve, onReview, onOpen, shift }: { setView: (view: View) => void; decisionResolved: boolean; onResolve: () => void; onReview: () => void; onOpen: (order: Order) => void; shift: Shift }) {
  return <>
    <div className="mb-8 flex flex-col justify-between gap-6 xl:flex-row xl:items-end"><div><Eyebrow>Northline FC-01 · Command desk</Eyebrow><h1 className="max-w-3xl font-display text-[48px] leading-[0.9] tracking-[-0.05em] sm:text-[66px]">Protect the promise.<br /><span className="text-ink/38">Keep the floor moving.</span></h1><p className="mt-5 max-w-xl text-[13px] leading-relaxed text-ink/55">One priority allocation needs a decision before the 16:00 carrier cut-off. Everything else is moving inside today's operating plan.</p></div><div className="flex shrink-0 items-center gap-3 rounded-2xl border border-ink/10 bg-[#f7f1e6] px-4 py-3"><div className="flex h-9 w-9 items-center justify-center rounded-xl bg-sage/15 text-sage-dark"><Gauge className="h-4 w-4" /></div><div><div className="font-mono text-[8px] uppercase tracking-[0.2em] text-ink/42">Live shift status</div><div className="mt-1 text-[12px] font-semibold">Steady, with one call.</div></div><span className="ml-2 h-2 w-2 animate-pulse rounded-full bg-sage" /></div></div>
    <div className="mb-8 grid grid-cols-2 gap-5 border-y border-ink/10 py-5 sm:grid-cols-4"><Metric label="Orders in motion" value="48" change="+12% vs yesterday" accent="signal" /><Metric label="Pick accuracy" value="99.3%" change="+0.4 vs plan" /><Metric label="Floor capacity" value="76%" change="11% headroom" accent="sage" /><Metric label="Recoverable now" value="37m" change="3 bottlenecks" /></div>
    <div className="mb-6 grid gap-5 xl:grid-cols-[1.45fr_0.85fr]"><Panel className="relative min-h-[280px] overflow-hidden bg-ink"><img src="/manus-storage/warehouse-floor-hero_b9e7ce33.jpg" alt="Organized warehouse floor with a visible picker route" className="absolute inset-0 h-full w-full object-cover opacity-72" /><div className="absolute inset-0 bg-gradient-to-r from-ink via-ink/42 to-transparent" /><div className="relative flex h-full min-h-[280px] flex-col justify-between p-6 text-white sm:p-8"><div><div className="flex items-center gap-2 font-mono text-[9px] uppercase tracking-[0.22em] text-signal"><span className="h-1.5 w-1.5 rounded-full bg-signal" /> W-01 / Fulfillment live</div><h2 className="mt-4 max-w-sm font-display text-[34px] leading-[0.95] tracking-[-0.04em]">Zone A is clear for the next move.</h2><p className="mt-3 max-w-sm text-[11px] leading-relaxed text-white/60">3 pickers · route W-26 · 126 m of duplicate travel removed</p></div><div className="flex items-end justify-between"><span className="rounded-full border border-white/15 bg-white/10 px-3 py-1.5 font-mono text-[9px] uppercase tracking-[0.18em] text-white/75">Shift {shift} · {shiftDetails[shift].time}</span><button onClick={() => setView("pick")} className="flex items-center gap-1.5 text-[11px] font-semibold text-white transition hover:text-signal">Open floor view <ExternalLink className="h-3.5 w-3.5" /></button></div></div></Panel><Panel className="p-6"><div className="flex items-center justify-between"><div><Eyebrow>Dispatch clock</Eyebrow><h2 className="font-display text-[27px] leading-none">Next hand-off</h2></div><Truck className="h-5 w-5 text-signal-dark" /></div><div className="mt-6 space-y-4"><div className="flex items-start gap-3"><span className="mt-1 h-2 w-2 rounded-full bg-signal" /><div className="flex-1"><div className="flex justify-between gap-2 text-[12px] font-semibold"><span>15:30 · Express</span><span className="font-mono text-[9px] text-signal-dark">6 pending QC</span></div><div className="mt-1 text-[10px] text-ink/45">Dock 02 · manifest lock in 22 min</div></div></div><div className="flex items-start gap-3"><span className="mt-1 h-2 w-2 rounded-full bg-sage" /><div className="flex-1"><div className="flex justify-between gap-2 text-[12px] font-semibold"><span>16:00 · Priority outbound</span><span className="font-mono text-[9px] text-sage-dark">SO-48219</span></div><div className="mt-1 text-[10px] text-ink/45">Dock 01 · decision required</div></div></div><div className="flex items-start gap-3"><span className="mt-1 h-2 w-2 rounded-full bg-ink/20" /><div className="flex-1"><div className="flex justify-between gap-2 text-[12px] font-semibold"><span>17:45 · Ground</span><span className="font-mono text-[9px] text-ink/45">24 safe</span></div><div className="mt-1 text-[10px] text-ink/45">Dock 03 · inside operating plan</div></div></div></div><Button variant="outline" className="mt-6 w-full border-ink/15 bg-transparent text-[11px]" onClick={() => setView("dispatch")}>Open dispatch board <ChevronRight className="ml-auto h-3.5 w-3.5" /></Button></Panel></div>
    <div className="mb-6"><FlowTrack active={decisionResolved ? 5 : 4} /></div>
    <div className="mb-6"><DecisionCard resolved={decisionResolved} onResolve={onResolve} onReview={onReview} /></div>
    <div className="grid gap-5 xl:grid-cols-[1.45fr_0.85fr]"><Panel className="overflow-hidden"><div className="flex items-end justify-between px-5 pb-4 pt-5 sm:px-6"><div><Eyebrow>Priority order queue</Eyebrow><h2 className="font-display text-[28px] leading-none">What moves next</h2></div><button className="flex items-center gap-1 text-[10px] font-semibold text-signal-dark" onClick={() => setView("orders")}>Open queue <ArrowUpRight className="h-3.5 w-3.5" /></button></div><div className="grid grid-cols-[1.4fr_1.1fr_0.5fr_0.8fr_0.55fr] gap-3 px-5 pb-2 font-mono text-[8px] uppercase tracking-[0.16em] text-ink/32 sm:px-6"><span>Customer / order</span><span>Work state</span><span>Units</span><span>Promise</span><span /></div>{orders.slice(0, 4).map(order => <OrderRow key={order.id} order={order} onOpen={onOpen} />)}</Panel><Panel className="p-5 sm:p-6"><div className="flex items-start justify-between"><div><Eyebrow>Inventory radar</Eyebrow><h2 className="font-display text-[28px] leading-none">Stock signals</h2></div><Boxes className="h-5 w-5 text-ink/30" /></div><div className="mt-5 space-y-4">{inventory.slice(0, 3).map(item => <div key={item.sku}><div className="flex justify-between gap-3"><div><div className="font-mono text-[9px] text-ink/46">{item.sku}</div><div className="mt-0.5 text-[11px] font-semibold">{item.name}</div></div><span className={cn("text-[10px] font-semibold", item.tone === "risk" ? "text-signal-dark" : item.tone === "watch" ? "text-[#8b731f]" : "text-sage-dark")}>{item.available} on hand</span></div><div className="mt-2 h-1.5 overflow-hidden rounded-full bg-ink/8"><div className={cn("h-full rounded-full", item.tone === "risk" ? "bg-signal" : item.tone === "watch" ? "bg-[#c6a535]" : "bg-sage")} style={{ width: `${Math.min(100, item.available / (item.floor * 2.2) * 100)}%` }} /></div></div>)}</div><div className="mt-5 rounded-xl border border-signal/20 bg-signal/8 p-3"><div className="flex gap-2"><AlertTriangle className="mt-0.5 h-3.5 w-3.5 shrink-0 text-signal-dark" /><div className="text-[10px] leading-relaxed text-ink/65"><span className="font-semibold text-ink">Reorder signal:</span> LUMA-200 will breach its safety floor after SO-48219. Suggested PO: 36 units.</div></div></div><Button variant="ghost" onClick={() => setView("inventory")} className="mt-3 h-8 px-0 text-[10px] font-semibold text-signal-dark hover:bg-transparent hover:text-ink">Review inventory <ChevronRight className="ml-1 h-3.5 w-3.5" /></Button></Panel></div>
  </>;
}

function OrderQueue({ onOpen, decisionResolved, onResolve }: { onOpen: (order: Order) => void; decisionResolved: boolean; onResolve: () => void }) {
  const [filter, setFilter] = useState("All active");
  const filtered = useMemo(() => filter === "All active" ? orders : filter === "At risk" ? orders.filter(o => o.risk === "At risk") : filter === "Ready to pick" ? orders.filter(o => o.status === "Allocated") : orders.filter(o => o.risk === "Held"), [filter]);
  return <><PageIntro eyebrow="Fulfillment control · Northline FC-01" title="Order queue" description="Ranked by promise risk, customer tier, and fulfillment readiness. Decisions stay visible alongside the work." action={<Button onClick={onResolve} className="bg-signal text-ink hover:bg-signal-dark">{decisionResolved ? <><Check className="mr-2 h-4 w-4" /> Split approved</> : <>Approve recommended split <ChevronRight className="ml-2 h-4 w-4" /></>}</Button>} /><div className="mb-5 flex flex-wrap items-center gap-2"><Pill active={filter === "All active"} onClick={() => setFilter("All active")}>All active · 48</Pill><Pill active={filter === "At risk"} onClick={() => setFilter("At risk")}>At risk · 1</Pill><Pill active={filter === "Ready to pick"} onClick={() => setFilter("Ready to pick")}>Ready to pick · 14</Pill><Pill active={filter === "Held"} onClick={() => setFilter("Held")}>Held · 2</Pill><span className="ml-auto hidden items-center gap-2 text-[10px] text-ink/42 sm:flex"><SlidersHorizontal className="h-3.5 w-3.5" /> Sort: <span className="font-semibold text-ink">priority</span></span></div><div className="grid gap-5 xl:grid-cols-[1.3fr_0.7fr]"><Panel className="overflow-hidden"><div className="flex items-center justify-between px-5 py-5 sm:px-6"><div><div className="font-mono text-[9px] uppercase tracking-[0.2em] text-ink/38">Promise-date order</div><h2 className="mt-1 font-display text-[28px] leading-none">Work sequence</h2></div><span className="font-mono text-[10px] text-ink/38">{filtered.length} visible</span></div><div className="hidden grid-cols-[1.4fr_1.1fr_0.5fr_0.8fr_0.55fr] gap-3 px-5 pb-2 font-mono text-[8px] uppercase tracking-[0.16em] text-ink/32 sm:grid sm:px-6"><span>Customer / order</span><span>Work state</span><span>Units</span><span>Promise</span><span /></div>{filtered.map(order => <OrderRow key={order.id} order={order} onOpen={onOpen} />)}{filtered.length === 0 ? <div className="p-10 text-center text-[12px] text-ink/45">No orders match this view.</div> : null}</Panel><Panel className="bg-[#eef1e7] p-6"><Eyebrow>Allocation scenario</Eyebrow><h2 className="font-display text-[32px] leading-[0.95]">Preserve the higher promise.</h2><p className="mt-3 text-[12px] leading-relaxed text-ink/57">The proposed trade-off makes service impact explicit before any stock moves.</p><div className="mt-7 space-y-5"><div className="flex gap-3"><span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-sage/20 text-sage-dark"><ShieldAlert className="h-3.5 w-3.5" /></span><div><div className="text-[11px] font-semibold">Nova Retail stays inside the 16:00 SLA.</div><div className="mt-1 text-[10px] leading-relaxed text-ink/48">7 units allocate now; 3 ship from inbound today.</div></div></div><div className="flex gap-3"><span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-signal/20 text-signal-dark"><Clock3 className="h-3.5 w-3.5" /></span><div><div className="text-[11px] font-semibold">Marlowe Market moves by one day.</div><div className="mt-1 text-[10px] leading-relaxed text-ink/48">Promise is revised before warehouse release.</div></div></div><div className="flex gap-3"><span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-ink/8 text-ink/60"><RouteIcon className="h-3.5 w-3.5" /></span><div><div className="text-[11px] font-semibold">No picker rework required.</div><div className="mt-1 text-[10px] leading-relaxed text-ink/48">The active route is already in Zone A.</div></div></div></div><Button onClick={onResolve} className="mt-8 w-full bg-signal text-ink hover:bg-signal-dark">{decisionResolved ? "Allocation approved" : "Approve recommended split"}<Check className="ml-auto h-3.5 w-3.5" /></Button></Panel></div></>;
}

function InventoryPage() {
  return <><PageIntro eyebrow="Stock health · Northline FC-01" title="Inventory radar" description="Available, reserved, and inbound stock appear together so allocation decisions do not create invisible shortages." action={<Button variant="outline" onClick={() => toast("Inventory export prepared for the current shift")} className="border-ink/15 bg-transparent"><Download className="mr-2 h-4 w-4" /> Export snapshot</Button>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{inventory.map(item => <Panel key={item.sku} className="p-5"><div className="flex items-center justify-between"><span className="font-mono text-[9px] text-ink/42">{item.location}</span><span className={cn("rounded-full px-2 py-1 text-[8px] font-semibold uppercase tracking-[0.12em]", item.tone === "risk" ? "bg-signal/15 text-signal-dark" : item.tone === "watch" ? "bg-[#f3e8bd] text-[#806719]" : "bg-sage/15 text-sage-dark")}>{item.health}</span></div><div className="mt-6 font-mono text-[11px] font-semibold tracking-[0.12em] text-ink/62">{item.sku}</div><div className="mt-1 text-[12px] text-ink/55">{item.name}</div><div className="mt-7 font-display text-[44px] leading-none tracking-[-0.05em]">{item.available}</div><div className="mt-1 font-mono text-[9px] uppercase tracking-[0.18em] text-ink/36">available</div><div className="mt-5 h-1.5 overflow-hidden rounded-full bg-ink/8"><div className={cn("h-full rounded-full", item.tone === "risk" ? "bg-signal" : item.tone === "watch" ? "bg-[#c6a535]" : "bg-sage")} style={{ width: `${Math.min(100, item.available / (item.floor * 2.2) * 100)}%` }} /></div><div className="mt-3 grid grid-cols-3 gap-2 border-t border-ink/8 pt-3 text-[9px]"><div><div className="font-mono text-ink/35">RESERVED</div><div className="mt-1 font-semibold">{item.reserved}</div></div><div><div className="font-mono text-ink/35">INBOUND</div><div className="mt-1 font-semibold">{item.inbound || "—"}</div></div><div><div className="font-mono text-ink/35">FLOOR</div><div className="mt-1 font-semibold">{item.floor}</div></div></div></Panel>)}</div><div className="mt-5 grid gap-5 lg:grid-cols-[1fr_0.75fr]"><Panel className="overflow-hidden bg-ink p-6 text-white sm:p-8"><div className="flex items-start justify-between"><div><Eyebrow className="text-white/45">Replenishment recommendation</Eyebrow><h2 className="max-w-lg font-display text-[40px] leading-[0.93] tracking-[-0.045em] text-white">Order 36 more<br /><span className="text-signal">LUMA-200</span> units.</h2><p className="mt-4 max-w-md text-[12px] leading-relaxed text-white/55">At current velocity, the SKU falls below its safety floor after today's priority split. Supplier lead time remains within the four-day threshold.</p></div><Sparkles className="h-6 w-6 text-signal" /></div><div className="mt-9 grid grid-cols-3 gap-4 border-t border-white/12 pt-5"><div><div className="font-display text-[26px]">11</div><div className="font-mono text-[8px] uppercase tracking-[0.18em] text-white/38">safety floor</div></div><div><div className="font-display text-[26px]">3</div><div className="font-mono text-[8px] uppercase tracking-[0.18em] text-white/38">inbound @ 14:20</div></div><div><div className="font-display text-[26px]">4 days</div><div className="font-mono text-[8px] uppercase tracking-[0.18em] text-white/38">lead time</div></div></div><Button onClick={() => toast("Draft purchase order created for 36 LUMA-200 units")} className="mt-7 bg-signal text-ink hover:bg-signal-dark">Create draft purchase order <ArrowUpRight className="ml-2 h-4 w-4" /></Button></Panel><Panel className="p-6"><Eyebrow>Inventory decisions</Eyebrow><h2 className="font-display text-[30px] leading-none">What changed this shift</h2><div className="mt-6 space-y-4">{[{ icon: ArrowDownRight, title: "LUMA-200 moved below safety floor", copy: "Priority split consumes 3 units of available headroom.", tone: "text-signal-dark bg-signal/15" }, { icon: ArrowUpRight, title: "ARC-040 inbound cover improved", copy: "24 units are now due against the next standard wave.", tone: "text-sage-dark bg-sage/15" }, { icon: PackageCheck, title: "NOVA-110 is stable", copy: "92 available with 31 units reserved for active orders.", tone: "text-ink/60 bg-ink/7" }].map(item => { const Icon = item.icon; return <div key={item.title} className="flex gap-3 border-b border-ink/8 pb-4 last:border-0 last:pb-0"><span className={cn("flex h-8 w-8 shrink-0 items-center justify-center rounded-xl", item.tone)}><Icon className="h-4 w-4" /></span><div><div className="text-[11px] font-semibold">{item.title}</div><div className="mt-1 text-[10px] leading-relaxed text-ink/48">{item.copy}</div></div></div>; })}</div></Panel></div></>;
}

function PickPage({ waveReleased, onRelease }: { waveReleased: boolean; onRelease: () => void }) {
  return <><PageIntro eyebrow="Floor execution · Northline FC-01" title="Pick & pack" description="Routes sequence items by zone and cut-off, keeping walkers productive while leaving exceptions clear to the floor lead." action={<Button onClick={onRelease} className="bg-signal text-ink hover:bg-signal-dark">{waveReleased ? <><Check className="mr-2 h-4 w-4" /> Wave released</> : <>Release wave <Zap className="ml-2 h-4 w-4" /></>}</Button>} /><div className="grid gap-5 xl:grid-cols-[1.1fr_0.9fr]"><Panel className="relative overflow-hidden bg-[#f4eddf] p-6 sm:p-8"><div className="relative z-10 max-w-sm"><Eyebrow>Recommended pick wave · W-26</Eyebrow><h2 className="font-display text-[40px] leading-[0.92] tracking-[-0.045em]">Zone A becomes the next best route.</h2><p className="mt-4 text-[12px] leading-relaxed text-ink/55">Bundle the urgent LUMA-200 allocation with two nearby orders. This removes 126 metres of duplicate travel.</p><Button onClick={onRelease} className="mt-6 bg-signal text-ink hover:bg-signal-dark">{waveReleased ? "Route active" : "Release wave"}<RouteIcon className="ml-2 h-4 w-4" /></Button></div><img src="/manus-storage/pick-route-visual_a6fe8988.jpg" alt="Isometric warehouse route illustration" className="mt-8 h-[230px] w-full rounded-xl object-cover mix-blend-multiply opacity-80" /><div className="mt-5 flex flex-wrap gap-2 font-mono text-[9px] uppercase tracking-[0.16em] text-ink/43"><span className="rounded-full border border-signal/40 bg-signal/15 px-3 py-1.5 text-signal-dark">A-03</span><span className="rounded-full border border-ink/12 bg-paper px-3 py-1.5">A-07</span><span className="rounded-full border border-ink/12 bg-paper px-3 py-1.5">PACK-02</span></div></Panel><Panel className="p-6 sm:p-8"><div className="flex items-start justify-between"><div><Eyebrow>Current task board</Eyebrow><h2 className="font-display text-[30px] leading-none">Floor hand-off</h2></div><ClipboardCheck className="h-5 w-5 text-sage-dark" /></div><div className="mt-7 space-y-1">{[{ state: "IN HAND", tone: "active", title: "Pick SO-48207 in Zone C", meta: "C-12 / BIN-04 · Kai M." }, { state: waveReleased ? "IN HAND" : "QUEUED", tone: waveReleased ? "active" : "queued", title: "Pick SO-48219 in Zone A", meta: waveReleased ? "A-03 / BIN-17 · Maya R." : "A-03 / BIN-17 · release on approval" }, { state: "COMPLETE", tone: "complete", title: "Pack SO-48175 at Station 04", meta: "PACK-04 · Gabe L." }, { state: "COMPLETE", tone: "complete", title: "Quality check SO-48162", meta: "QC-01 · Casey R." }].map(task => <div key={task.title} className="flex items-center gap-3 border-b border-ink/8 py-4 last:border-0"><span className={cn("flex h-8 w-8 shrink-0 items-center justify-center rounded-full", task.tone === "active" ? "bg-signal/20 text-signal-dark" : task.tone === "complete" ? "bg-sage/18 text-sage-dark" : "bg-ink/7 text-ink/45")}>{task.tone === "complete" ? <Check className="h-3.5 w-3.5" /> : task.tone === "active" ? <PackageOpen className="h-3.5 w-3.5" /> : <Clock3 className="h-3.5 w-3.5" />}</span><div className="min-w-0 flex-1"><div className="text-[11px] font-semibold">{task.title}</div><div className="mt-1 truncate font-mono text-[9px] uppercase tracking-[0.12em] text-ink/38">{task.meta}</div></div><span className={cn("font-mono text-[8px] uppercase tracking-[0.14em]", task.tone === "active" ? "text-signal-dark" : task.tone === "complete" ? "text-sage-dark" : "text-ink/35")}>{task.state}</span></div>)}</div><div className="mt-7 grid grid-cols-3 gap-3 rounded-xl bg-[#f7f1e6] p-4"><Metric label="Pickers" value="3" change="Zone A / C" /><Metric label="Travel saved" value="126m" change="vs split wave" accent="sage" /><Metric label="Pack queue" value="4" change="2 stations free" /></div></Panel></div></>;
}

function DispatchPage() {
  return <><PageIntro eyebrow="Outbound control · Northline FC-01" title="Dispatch board" description="Carrier deadlines, manifest readiness, and dock sequencing are joined in one clear shipping view." action={<Button onClick={() => toast("Dispatch manifest exported")} variant="outline" className="border-ink/15 bg-transparent"><Download className="mr-2 h-4 w-4" /> Export manifest</Button>} /><Panel className="relative mb-5 min-h-[320px] overflow-hidden bg-ink"><img src="/manus-storage/dispatch-dock-visual_fd3d1174.jpg" alt="Delivery van at a warehouse loading dock" className="absolute inset-0 h-full w-full object-cover opacity-75" /><div className="absolute inset-0 bg-gradient-to-r from-ink via-ink/65 to-transparent" /><div className="relative flex min-h-[320px] flex-col justify-between p-6 text-white sm:p-9"><div><Eyebrow className="text-white/55">Express collection at 15:30</Eyebrow><h2 className="max-w-xl font-display text-[43px] leading-[0.92] tracking-[-0.045em]">6 orders need quality checks before the van closes.</h2><p className="mt-4 max-w-md text-[12px] leading-relaxed text-white/55">Dock 02 has capacity for the express cage; workers are assigned and no carrier delay is forecast.</p></div><div className="grid max-w-xl grid-cols-3 gap-4 border-t border-white/15 pt-5"><Metric label="To manifest lock" value="22 min" accent="signal" /><Metric label="Orders sealed" value="18 / 24" /><Metric label="On-time forecast" value="92%" accent="sage" /></div></div></Panel><Panel className="overflow-hidden"><div className="grid grid-cols-[0.9fr_1.1fr_0.7fr_0.8fr_0.7fr] gap-3 bg-[#f7f1e6] px-5 py-3 font-mono text-[8px] uppercase tracking-[0.18em] text-ink/38 sm:px-6"><span>Manifest</span><span>Carrier</span><span>Dock</span><span>Cut-off</span><span>Status</span></div>{[{ manifest: "EXP-2148", carrier: "Express", dock: "D-02", cutoff: "15:30", status: "Loading", tone: "bg-signal/15 text-signal-dark" }, { manifest: "PRIO-602", carrier: "Priority", dock: "D-01", cutoff: "16:00", status: "Staged", tone: "bg-sage/15 text-sage-dark" }, { manifest: "GRD-071", carrier: "Ground", dock: "D-03", cutoff: "17:45", status: "Open", tone: "bg-ink/7 text-ink/48" }].map(row => <div key={row.manifest} className="grid grid-cols-[0.9fr_1.1fr_0.7fr_0.8fr_0.7fr] items-center gap-3 border-t border-ink/8 px-5 py-4 text-[11px] sm:px-6"><span className="font-mono text-[10px] text-ink/55">{row.manifest}</span><span>{row.carrier}</span><span className="font-mono text-[10px] text-ink/55">{row.dock}</span><span className="font-mono text-[10px] text-ink/55">{row.cutoff}</span><span><span className={cn("rounded-full px-2 py-1 text-[9px]", row.tone)}>{row.status}</span></span></div>)}</Panel><div className="mt-5 grid gap-4 sm:grid-cols-3">{[{ icon: PackageCheck, title: "Quality checks", value: "6 pending", copy: "QC-01 is the highest load." }, { icon: Layers3, title: "Dock capacity", value: "2 spaces", copy: "D-02 can absorb the express cage." }, { icon: Truck, title: "Carrier confidence", value: "92% on time", copy: "No delay forecast this shift." }].map(item => { const Icon = item.icon; return <Panel key={item.title} className="p-5"><Icon className="h-5 w-5 text-signal-dark" /><div className="mt-5 text-[11px] text-ink/45">{item.title}</div><div className="mt-1 font-display text-[24px] leading-none">{item.value}</div><div className="mt-2 text-[10px] text-ink/45">{item.copy}</div></Panel>; })}</div></>;
}

function AnalyticsPage() {
  const [range, setRange] = useState<"today" | "week">("today");
  const isWeek = range === "week";
  const chartData = isWeek ? throughput.map((point, index) => ({ ...point, orders: point.orders + 4 + (index % 3) * 2 })) : throughput;
  return <><PageIntro eyebrow="Operational intelligence · Northline FC-01" title="Flow analysis" description="The operating picture focuses on throughput, not vanity metrics: where time accumulates and what intervention removes it." action={<div className="flex items-center gap-2"><Pill active={!isWeek} onClick={() => { setRange("today"); toast("Analytics range set to Today"); }}>Today</Pill><Pill active={isWeek} onClick={() => { setRange("week"); toast("Analytics range set to Last 7 shifts"); }}>Last 7 shifts</Pill></div>} /><div className="grid gap-5 xl:grid-cols-[1.25fr_0.75fr]"><Panel className="p-5 sm:p-6"><div className="flex items-start justify-between"><div><Eyebrow>Orders cleared per hour</Eyebrow><h2 className="font-display text-[29px] leading-none">Throughput holds above plan.</h2><p className="mt-2 text-[11px] text-ink/45">{isWeek ? "Seven-shift operating average versus a 60-order-per-hour operating target." : "Today's active shift versus a 60-order-per-hour operating target."}</p></div><div className="flex items-center gap-2 font-mono text-[9px] text-ink/40"><span className="h-2 w-2 rounded-full bg-signal" /> Actual <span className="ml-2 h-2 w-2 rounded-full bg-ink/18" /> Target</div></div><div className="mt-7 h-[280px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={chartData} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}><CartesianGrid vertical={false} stroke="#0f283712" /><XAxis dataKey="hour" axisLine={false} tickLine={false} tick={{ fill: "#0f283766", fontSize: 10, fontFamily: "IBM Plex Mono" }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: "#0f283766", fontSize: 10, fontFamily: "IBM Plex Mono" }} domain={[0, 80]} /><ChartTooltip cursor={{ fill: "#0f283708" }} contentStyle={{ borderRadius: 10, border: "1px solid #0f283718", background: "#fffdf8", fontSize: 11 }} /><Bar dataKey="orders" fill="#E7A83B" radius={[5, 5, 0, 0]} barSize={26} /></BarChart></ResponsiveContainer></div></Panel><Panel className="bg-[#eef1e7] p-6"><Eyebrow>Bottleneck watch</Eyebrow><h2 className="font-display text-[31px] leading-none">Minutes recoverable now</h2><div className="mt-7 space-y-5">{[{ value: "18", title: "Quality-check queue", copy: "6 orders · QC-01 is highest load", tone: "text-signal-dark" }, { value: "12", title: "Duplicate aisle travel", copy: "Route W-26 removes 126 m", tone: "text-sage-dark" }, { value: "07", title: "Allocation decision", copy: "Priority stock exception pending", tone: "text-ink/70" }].map(item => <div key={item.title} className="flex items-start gap-4 border-b border-ink/10 pb-4 last:border-0 last:pb-0"><div className={cn("font-display text-[39px] leading-none tracking-[-0.05em]", item.tone)}>{item.value}</div><div className="pt-1"><div className="text-[11px] font-semibold">{item.title}</div><div className="mt-1 text-[10px] text-ink/45">{item.copy}</div></div></div>)}</div><div className="mt-7 grid grid-cols-2 gap-3"><div className="rounded-xl bg-paper p-4"><div className="font-mono text-[8px] uppercase tracking-[0.15em] text-ink/38">Pick accuracy</div><div className="mt-2 font-display text-[27px] leading-none">99.3%</div><div className="mt-1 text-[9px] text-sage-dark">+0.4 vs plan</div></div><div className="rounded-xl bg-paper p-4"><div className="font-mono text-[8px] uppercase tracking-[0.15em] text-ink/38">Pack dwell</div><div className="mt-2 font-display text-[27px] leading-none">6.2m</div><div className="mt-1 text-[9px] text-sage-dark">-1.1 min</div></div></div></Panel></div><div className="mt-5 grid gap-5 sm:grid-cols-3">{[{ icon: ArrowUpRight, value: "+12%", label: "Orders in motion", copy: "vs previous shift" }, { icon: ArrowDownRight, value: "-8 min", label: "Average dwell", copy: "after route release" }, { icon: GitBranch, value: "3", label: "Interventions", copy: "to protect today's cut-offs" }].map(item => { const Icon = item.icon; return <Panel key={item.label} className="p-5"><div className="flex items-center justify-between"><div className="font-mono text-[9px] uppercase tracking-[0.18em] text-ink/42">{item.label}</div><Icon className="h-4 w-4 text-signal-dark" /></div><div className="mt-5 font-display text-[33px] leading-none">{item.value}</div><div className="mt-2 text-[10px] text-ink/45">{item.copy}</div></Panel>; })}</div></>;
}

function OrderDrawer({ order, onClose }: { order: Order; onClose: () => void }) {
  return <div className="fixed inset-0 z-50 flex justify-end"><button aria-label="Close order details" className="absolute inset-0 bg-ink/25 backdrop-blur-[2px]" onClick={onClose} /><aside className="relative h-full w-full max-w-[480px] overflow-y-auto border-l border-ink/10 bg-paper p-6 shadow-[-20px_0_70px_rgba(15,40,55,0.16)] sm:p-8"><div className="flex items-start justify-between"><div><Eyebrow>Order detail · {order.id}</Eyebrow><h2 className="font-display text-[38px] leading-[0.92] tracking-[-0.04em]">{order.customer}</h2><div className="mt-2 font-mono text-[10px] uppercase tracking-[0.15em] text-ink/42">{order.sku} · {order.product}</div></div><button onClick={onClose} className="rounded-xl border border-ink/10 p-2 text-ink/45 transition hover:bg-ink/5 hover:text-ink" aria-label="Close"><X className="h-4 w-4" /></button></div><div className="mt-8 grid grid-cols-2 gap-3"><div className="rounded-xl bg-[#f7f1e6] p-4"><div className="font-mono text-[8px] uppercase tracking-[0.15em] text-ink/38">Promise</div><div className="mt-2 font-display text-[28px] leading-none">{order.promise}</div><div className="mt-1 text-[10px] text-ink/45">{order.carrier}</div></div><div className="rounded-xl bg-[#f7f1e6] p-4"><div className="font-mono text-[8px] uppercase tracking-[0.15em] text-ink/38">Allocated</div><div className="mt-2 font-display text-[28px] leading-none">{order.allocated} / {order.units}</div><div className="mt-1 text-[10px] text-ink/45">{order.status}</div></div></div><div className="mt-7"><div className="font-mono text-[9px] uppercase tracking-[0.2em] text-ink/38">Decision context</div><div className="mt-3 rounded-2xl border border-signal/25 bg-signal/8 p-5"><div className="flex gap-3"><AlertTriangle className="mt-0.5 h-4 w-4 shrink-0 text-signal-dark" /><div><div className="text-[12px] font-semibold">{order.risk === "At risk" ? "Allocation decision required" : "Order is moving inside plan"}</div><div className="mt-2 text-[11px] leading-relaxed text-ink/57">{order.note}</div></div></div></div></div><div className="mt-7"><div className="font-mono text-[9px] uppercase tracking-[0.2em] text-ink/38">Fulfillment chain</div><div className="mt-4 space-y-0">{[{ label: "Order created", state: "complete" }, { label: "Priority determined", state: "complete" }, { label: "Inventory checked", state: order.allocated > 0 ? "complete" : "current" }, { label: "Stock allocated", state: order.status === "Awaiting allocation" ? "current" : "complete" }, { label: "Picking and packing", state: order.status === "Picking" || order.status === "Quality check" ? "current" : "next" }, { label: "Quality check", state: order.status === "Quality check" ? "current" : "next" }, { label: "Dispatch", state: "next" }].map((step, index) => <div key={step.label} className="flex items-center gap-3"><div className="flex w-6 flex-col items-center"><span className={cn("flex h-5 w-5 items-center justify-center rounded-full border", step.state === "complete" ? "border-sage bg-sage text-white" : step.state === "current" ? "border-signal bg-signal text-ink" : "border-ink/15 text-ink/30")}>{step.state === "complete" ? <Check className="h-3 w-3" /> : index + 1}</span>{index < 6 ? <span className={cn("h-6 w-px", step.state === "complete" ? "bg-sage/60" : "bg-ink/12")} /> : null}</div><span className={cn("pb-6 text-[11px]", step.state === "current" ? "font-semibold text-ink" : step.state === "complete" ? "text-ink/62" : "text-ink/35")}>{step.label}{step.state === "current" ? <span className="ml-2 font-mono text-[8px] uppercase tracking-[0.15em] text-signal-dark">current</span> : null}</span></div>)}</div></div><Button className="mt-4 w-full bg-signal text-ink hover:bg-signal-dark" onClick={() => { toast(`Action queued for ${order.id}`); onClose(); }}>Open next action <ChevronRight className="ml-auto h-4 w-4" /></Button></aside></div>;
}

function SearchOverlay({ onClose, setView }: { onClose: () => void; setView: (view: View) => void }) {
  return <div className="fixed inset-0 z-50 flex items-start justify-center bg-ink/25 px-4 pt-[14vh] backdrop-blur-[2px]"><div className="w-full max-w-xl rounded-2xl border border-ink/10 bg-paper p-4 shadow-[0_24px_80px_rgba(15,40,55,0.18)]"><div className="flex items-center gap-3 border-b border-ink/10 px-2 pb-3"><Search className="h-4 w-4 text-ink/38" /><input autoFocus placeholder="Search orders, SKUs, zones…" className="flex-1 bg-transparent text-[13px] outline-none placeholder:text-ink/35" /><button onClick={onClose} className="rounded-lg p-1 text-ink/38 hover:bg-ink/5"><X className="h-4 w-4" /></button></div><div className="mt-3 font-mono text-[9px] uppercase tracking-[0.18em] text-ink/35">Jump to workspace</div><div className="mt-2 grid gap-1 sm:grid-cols-2">{navItems.map(item => { const Icon = item.icon; return <button key={item.id} onClick={() => { setView(item.id); onClose(); }} className="flex items-center gap-3 rounded-xl px-3 py-3 text-left text-[11px] transition hover:bg-[#f7f1e6]"><Icon className="h-4 w-4 text-signal-dark" />{item.label}<ChevronRight className="ml-auto h-3.5 w-3.5 text-ink/25" /></button>; })}</div></div></div>;
}

export default function Home() {
  const [view, setView] = useState<View>("command");
  const [shift, setShift] = useState<Shift>("B");
  const [decisionResolved, setDecisionResolved] = useState(false);
  const [waveReleased, setWaveReleased] = useState(false);
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [searchOpen, setSearchOpen] = useState(false);
  const handleResolve = () => { setDecisionResolved(true); toast.success("Allocation approved", { description: "7 units released to SO-48219. Split shipment and audit note created." }); };
  const handleRelease = () => { setWaveReleased(true); toast.success("Wave W-26 released", { description: "Zone A is now the active pick route." }); };
  const content = view === "command" ? <CommandDesk setView={setView} shift={shift} decisionResolved={decisionResolved} onResolve={handleResolve} onReview={() => setView("orders")} onOpen={setSelectedOrder} /> : view === "orders" ? <OrderQueue onOpen={setSelectedOrder} decisionResolved={decisionResolved} onResolve={handleResolve} /> : view === "inventory" ? <InventoryPage /> : view === "pick" ? <PickPage waveReleased={waveReleased} onRelease={handleRelease} /> : view === "dispatch" ? <DispatchPage /> : <AnalyticsPage />;
  return <AppShell view={view} setView={setView} shift={shift} onShiftChange={setShift} onSearch={() => setSearchOpen(true)}><div className="mb-5 flex items-center justify-between lg:hidden"><div className="flex items-center gap-2 overflow-x-auto pb-1">{navItems.map(item => <button key={item.id} onClick={() => setView(item.id)} className={cn("whitespace-nowrap rounded-full border px-3 py-1.5 text-[10px]", view === item.id ? "border-ink bg-ink text-paper" : "border-ink/12 text-ink/48")}>{item.label}</button>)}</div><button className="ml-3 shrink-0 rounded-lg border border-ink/10 p-2" onClick={() => setSearchOpen(true)} aria-label="Search"><Search className="h-3.5 w-3.5" /></button></div>{content}{selectedOrder ? <OrderDrawer order={selectedOrder} onClose={() => setSelectedOrder(null)} /> : null}{searchOpen ? <SearchOverlay onClose={() => setSearchOpen(false)} setView={setView} /> : null}</AppShell>;
}
